        {
          "start": 1308.08,
          "duration": 6.959,
          "text": "なんかおチャンネルとかの撮影しててもあ"
        },
        {
          "start": 1311.96,
          "duration": 5.12,
          "text": "こいつここ切ったみたいなうん分かる時"
        },
        {
          "start": 1315.039,
          "duration": 4.961,
          "text": "あるじゃんあ言い直してるみたいなあこ"
        },
        {
          "start": 1317.08,
          "duration": 5.479,
          "text": "切るつもりだみたいうんなんかそういう"
        },
        {
          "start": 1320.0,
          "duration": 5.32,
          "text": "感じになってくねどんどんやっぱ普通に"
        },
        {
          "start": 1322.559,
          "duration": 5.681,
          "text": "喋ってるようでいてまそうだよねうん"
        },
        {
          "start": 1325.32,
          "duration": 5.0,
          "text": "なんか切り張りを自然にやっぱするように"
        },
        {
          "start": 1328.24,
          "duration": 6.799,
          "text": "なってるみたいな意識しちゃうよねそこは"
        },
        {
          "start": 1330.32,
          "duration": 5.599,
          "text": "うんそれって誰なんだみたいな誰誰がって"
        },
        {
          "start": 1335.039,
          "duration": 5.0,
          "text": "いう"
        },
        {
          "start": 1335.919,
          "duration": 6.24,
          "text": "そのそうねすごいんですよだから誰がこう"
        },
        {
          "start": 1340.039,
          "duration": 4.921,
          "text": "させてるんだろうっていうそう無言のうち"
        },
        {
          "start": 1342.159,
          "duration": 4.921,
          "text": "にああここ切るなって思いながら会話し"
        },
        {
          "start": 1344.96,
          "duration": 4.599,
          "text": "てる時のあの感じなんなんですかねうん"
        },
        {
          "start": 1347.08,
          "duration": 4.68,
          "text": "なんかねすごいそれが分かるのが要は"
        },
        {
          "start": 1349.559,
          "duration": 5.761,
          "text": "やっぱ仕事になるっていうことなんじゃ"
        },
        {
          "start": 1351.76,
          "duration": 5.72,
          "text": "ないだって職場だってさ仕事だって別に"
        },
        {
          "start": 1355.32,
          "duration": 5.239,
          "text": "あんな感じになる人ないわけじゃない職場"
        },
        {
          "start": 1357.48,
          "duration": 6.319,
          "text": "ってなんか婚は静かにしてとかさなんか"
        },
        {
          "start": 1360.559,
          "duration": 6.401,
          "text": "上司に話聞きに行く時はなんかちょっと"
        },
        {
          "start": 1363.799,
          "duration": 5.801,
          "text": "こう貸しづいてすいませんみたいなうん"
        },
        {
          "start": 1366.96,
          "duration": 4.68,
          "text": "相談いいすかなんかさ別にそんなこと"
        },
        {
          "start": 1369.6,
          "duration": 6.04,
          "text": "ルールじゃないんだけどなんかもうみんな"
        },
        {
          "start": 1371.64,
          "duration": 8.8,
          "text": "で暗黙で作ってこうそれがやっぱも仕事に"
        },
        {
          "start": 1375.64,
          "duration": 4.8,
          "text": "なるっていうことでなんか俺らもようん"
        },
        {
          "start": 1382.6,
          "duration": 6.36,
          "text": "うんさんなんてもうずっとはか前からもん"
        },
        {
          "start": 1386.44,
          "duration": 4.92,
          "text": "ターンを超えてきて通りすぎて最初は"
        },
        {
          "start": 1388.96,
          "duration": 5.16,
          "text": "わかんないけどもうちょっとねなんか"
        },
        {
          "start": 1391.36,
          "duration": 6.76,
          "text": "いろんな人間みて言ったらあれだ"
        },
        {
          "start": 1394.12,
          "duration": 6.799,
          "text": "けど色々残してたノイズがある人だったん"
        },
        {
          "start": 1398.12,
          "duration": 6.08,
          "text": "ですよ最初はそうそうだろうねうノイズが"
        },
        {
          "start": 1400.919,
          "duration": 6.601,
          "text": "いつか金なくなったもう無駄なものなんて"
        },
        {
          "start": 1404.2,
          "duration": 7.359,
          "text": "ないのかもねプロ中のプロですが入院し"
        },
        {
          "start": 1407.52,
          "duration": 6.96,
          "text": "てるも食の食レポしておいしいグキキって"
        },
        {
          "start": 1411.559,
          "duration": 6.521,
          "text": "首をやってましたちゃんとうんすごいわ"
        },
        {
          "start": 1414.48,
          "duration": 7.16,
          "text": "やれないもんなあのグキは何なのってもう"
        },
        {
          "start": 1418.08,
          "duration": 6.88,
          "text": "今や意味がなくなってるんですあの確かに"
        },
        {
          "start": 1421.64,
          "duration": 6.56,
          "text": "あのグキ全く意味がない確かにエルゴ"
        },
        {
          "start": 1424.96,
          "duration": 4.719,
          "text": "ベビーバウンサーキみたいななんでグキな"
        },
        {
          "start": 1428.2,
          "duration": 5.52,
          "text": "んだよみたい"
        },
        {
          "start": 1429.679,
          "duration": 7.6,
          "text": "なあれはいいよあれ面白いこれすごいけど"
        },
        {
          "start": 1433.72,
          "duration": 5.24,
          "text": "何か入れてるよね武器をないんですよね"
        },
        {
          "start": 1437.279,
          "duration": 6.64,
          "text": "そういうことじゃない"
        },
        {
          "start": 1438.96,
          "duration": 6.92,
          "text": "すごいよねいや俺最初のさ妊娠発覚の"
        },
        {
          "start": 1443.919,
          "duration": 4.201,
          "text": "ところでHIKAKINさんがめっちゃ"
        },
        {
          "start": 1445.88,
          "duration": 5.44,
          "text": "匂い変えれんだよなんかうんうんうんそう"
        },
        {
          "start": 1448.12,
          "duration": 8.24,
          "text": "そうそうですごい匂い嗅いでるからえ俺"
        },
        {
          "start": 1451.32,
          "duration": 8.52,
          "text": "匂いでわかったのええと思ってえちょ一瞬"
        },
        {
          "start": 1456.36,
          "duration": 6.72,
          "text": "怖くなって妊婦の匂いがするなちょ"
        },
        {
          "start": 1459.84,
          "duration": 7.16,
          "text": "ちょっとそう思っちゃって狼の前"
        },
        {
          "start": 1463.08,
          "duration": 6.64,
          "text": "何ちょっと怖く最初だけねそんなわけは"
        },
        {
          "start": 1467.0,
          "duration": 5.279,
          "text": "ないんですけどない匂いで鍵つけたって"
        },
        {
          "start": 1469.72,
          "duration": 6.199,
          "text": "ことみたいなちょっと一瞬勘違ちゃいまし"
        },
        {
          "start": 1472.279,
          "duration": 6.201,
          "text": "たけど本当おめでたいことですしそあの俺"
        },
        {
          "start": 1475.919,
          "duration": 5.64,
          "text": "どうしようと思ってたもんその人生に"
        },
        {
          "start": 1478.48,
          "duration": 6.679,
          "text": "関わるみたいなあのすごいねデマも流れて"
        },
        {
          "start": 1481.559,
          "duration": 8.12,
          "text": "ましたけどそのさん"
        },
        {
          "start": 1485.159,
          "duration": 7.0,
          "text": "がそんなわけないそ予告してるわけない"
        },
        {
          "start": 1489.679,
          "duration": 4.72,
          "text": "そんそんなわけないそんなわけななんか"
        },
        {
          "start": 1492.159,
          "duration": 4.361,
          "text": "ちょっとざわっとしてそうキさんが"
        },
        {
          "start": 1494.399,
          "duration": 5.241,
          "text": "ちょっと熱をね出されてたってことで"
        },
        {
          "start": 1496.52,
          "duration": 7.08,
          "text": "そんな出もちょっとうん"
        },
        {
          "start": 1499.64,
          "duration": 7.56,
          "text": "うんっったんようんいや塩金だったらどう"
        },
        {
          "start": 1503.6,
          "duration": 7.199,
          "text": "しようこれと思ってそうね磯金の次すに俺"
        },
        {
          "start": 1507.2,
          "duration": 6.68,
          "text": "怒るかもなみたいなちょっとその心配して"
        },
        {
          "start": 1510.799,
          "duration": 7.561,
          "text": "たんですよ味噌金実店舗で販売みたいな"
        },
        {
          "start": 1513.88,
          "duration": 8.32,
          "text": "こと言い始めたらちょさすがに切れよか"
        },
        {
          "start": 1518.36,
          "duration": 6.96,
          "text": "なあまりにもだぞっていうだ本当良かった"
        },
        {
          "start": 1522.2,
          "duration": 4.92,
          "text": "なというかおめでたいなと素直に本当に"
        },
        {
          "start": 1525.32,
          "duration": 5.88,
          "text": "うんうんそうねやっぱすぐ行ってました"
        },
        {
          "start": 1527.12,
          "duration": 7.36,
          "text": "もんねそのねうんあの子供が生まれました"
        },
        {
          "start": 1531.2,
          "duration": 7.28,
          "text": "みたいなことをねね本当に怪光1番で言っ"
        },
        {
          "start": 1534.48,
          "duration": 6.28,
          "text": "てたんでああ良かった思いますよ安心させ"
        },
        {
          "start": 1538.48,
          "duration": 5.52,
          "text": "たかったってのもあるでしょうねうんパパ"
        },
        {
          "start": 1540.76,
          "duration": 7.6,
          "text": "パパパパになれんのパパになれんのあれは"
        },
        {
          "start": 1544.0,
          "duration": 6.96,
          "text": "で2回目でしょ言うなそんなこと言うな2"
        },
        {
          "start": 1548.36,
          "duration": 6.08,
          "text": "回目かわかん"
        },
        {
          "start": 1550.96,
          "duration": 7.719,
          "text": "ない曲言まで行くと人間っていうのはここ"
        },
        {
          "start": 1554.44,
          "duration": 8.16,
          "text": "まで進化するんだなっていあすごい素そこ"
        },
        {
          "start": 1558.679,
          "duration": 7.24,
          "text": "へ向もうきましょ新しいです本当にうん"
        },
        {
          "start": 1562.6,
          "duration": 4.16,
          "text": "全てを切り刻んで売っていこうここまでは"
        },
        {
          "start": 1565.919,
          "duration": 6.76,
          "text": "して"
        },
        {
          "start": 1566.76,
          "duration": 9.36,
          "text": "ない言い方が悪いな意味すごいね我々も"
        },
        {
          "start": 1572.679,
          "duration": 6.841,
          "text": "覚悟勇気をもらいましたあの動画から本当"
        },
        {
          "start": 1576.12,
          "duration": 5.679,
          "text": "にちょうど同日だったしね8月1日で色々"
        },
        {
          "start": 1579.52,
          "duration": 4.72,
          "text": "あった時からそうなんかアンケート機能と"
        },
        {
          "start": 1581.799,
          "duration": 6.641,
          "text": "かも使ってもう登録してくれましたか"
        },
        {
          "start": 1584.24,
          "duration": 6.76,
          "text": "みたいなアンケート出すんですよあもはい"
        },
        {
          "start": 1588.44,
          "duration": 5.8,
          "text": "もんな怖くてうんそういうこと言うことで"
        },
        {
          "start": 1591.0,
          "duration": 5.48,
          "text": "なんか言われる文句を想像してそううん"
        },
        {
          "start": 1594.24,
          "duration": 4.96,
          "text": "引いてしまうから何かから逃れようとし"
        },
        {
          "start": 1596.48,
          "duration": 5.48,
          "text": "てるからやっぱり俺たちもちゃんとうん"
        },
        {
          "start": 1599.2,
          "duration": 6.68,
          "text": "これが現実だから000人の修行じゃない"
        },
        {
          "start": 1601.96,
          "duration": 7.68,
          "text": "んだそうなの本当高い岩の上にいるん"
        },
        {
          "start": 1605.88,
          "duration": 6.2,
          "text": "でしょ俺たち細くて高い岩の上で座禅組ん"
        },
        {
          "start": 1609.64,
          "duration": 6.639,
          "text": "で終わった後老師に褒めてもらおうとする"
        },
        {
          "start": 1612.08,
          "duration": 6.319,
          "text": "もうその正明がやだわもう老師なんてい"
        },
        {
          "start": 1616.279,
          "duration": 5.441,
          "text": "ない"
        },
        {
          "start": 1618.399,
          "duration": 5.841,
          "text": "いうそう老師なしでここを生きてると"
        },
        {
          "start": 1621.72,
          "duration": 6.199,
          "text": "やっぱ思わないといけない本当にそうだよ"
        },
        {
          "start": 1624.24,
          "duration": 7.08,
          "text": "なねねこれからのなんかおの変化に注目"
        },
        {
          "start": 1627.919,
          "duration": 7.36,
          "text": "です変わりますね確か本当にマジで動き"
        },
        {
          "start": 1631.32,
          "duration": 6.44,
          "text": "始めてる感じはある実際本当にうんはいと"
        },
        {
          "start": 1635.279,
          "duration": 3.721,
          "text": "いうわけなんではい今週はこの辺で"
        },
        {
          "start": 1637.76,
          "duration": 4.36,
          "text": "ありがとうございましたありがとうござい"
        },
        {
          "start": 1639.0,
          "duration": 3.12,
          "text": "ましたあり"
        }
