        {
          "start": 810.959,
          "duration": 5.601,
          "text": "うんだったらより最悪だろそれそしたら君"
        },
        {
          "start": 814.399,
          "duration": 4.361,
          "text": "たちはどう切るかも回収ってことになるも"
        },
        {
          "start": 816.56,
          "duration": 4.519,
          "text": "そうなるよねハッシンしたやつの歌なんか"
        },
        {
          "start": 818.76,
          "duration": 6.24,
          "text": "聞きたくねえよみたいな感覚にもなる"
        },
        {
          "start": 821.079,
          "duration": 7.32,
          "text": "だろうねそうなんだ今うん急にねこの重く"
        },
        {
          "start": 825.0,
          "duration": 5.8,
          "text": "なる怖さというかねうんそうなんですよね"
        },
        {
          "start": 828.399,
          "duration": 4.601,
          "text": "なんかほとその運用ってやっぱどうしても"
        },
        {
          "start": 830.8,
          "duration": 5.039,
          "text": "ギャップがあるわけですけどそのギャップ"
        },
        {
          "start": 833.0,
          "duration": 7.399,
          "text": "の距離感がどんどんわかんなくなっている"
        },
        {
          "start": 835.839,
          "duration": 8.201,
          "text": "感じはしますよね誰の誰の顔色うん"
        },
        {
          "start": 840.399,
          "duration": 7.36,
          "text": "あ確かに誰が始めたんだっていう気持ちは"
        },
        {
          "start": 844.04,
          "duration": 5.359,
          "text": "あるよねなんかねうん生徒どう思ったんだ"
        },
        {
          "start": 847.759,
          "duration": 4.961,
          "text": "生"
        },
        {
          "start": 849.399,
          "duration": 5.88,
          "text": "ねなんか多分集められたんだろうね集会"
        },
        {
          "start": 852.72,
          "duration": 7.08,
          "text": "みた集められてちょっと大切な話があり"
        },
        {
          "start": 855.279,
          "duration": 7.8,
          "text": "ますみたいな本行のえ校長がですねうんあ"
        },
        {
          "start": 859.8,
          "duration": 6.039,
          "text": "あの校長だ言ってえコンビニでうん"
        },
        {
          "start": 863.079,
          "duration": 5.961,
          "text": "レギュラーサイズのコーヒーを買ってうん"
        },
        {
          "start": 865.839,
          "duration": 6.881,
          "text": "ラージのボタンを押すということをええ"
        },
        {
          "start": 869.04,
          "duration": 5.919,
          "text": "繰り返したのでええ超会"
        },
        {
          "start": 872.72,
          "duration": 6.0,
          "text": "名え"
        },
        {
          "start": 874.959,
          "duration": 6.361,
          "text": "えええてなるよねそなも引いちゃうよね"
        },
        {
          "start": 878.72,
          "duration": 5.559,
          "text": "なんかちょっとそんな厳しいの大人って"
        },
        {
          "start": 881.32,
          "duration": 5.199,
          "text": "みたいな中学生って何でもちゃかすけど"
        },
        {
          "start": 884.279,
          "duration": 6.041,
          "text": "これはちょっと困惑が先ちゃうこれは"
        },
        {
          "start": 886.519,
          "duration": 7.041,
          "text": "ちょっとドン引きかもしんないね"
        },
        {
          "start": 890.32,
          "duration": 7.639,
          "text": "シンとんでもねえことになったなみたいな"
        },
        {
          "start": 893.56,
          "duration": 5.68,
          "text": "うんすごいよなボだったんだとかとも"
        },
        {
          "start": 897.959,
          "duration": 4.24,
          "text": "ちょっと違う"
        },
        {
          "start": 899.24,
          "duration": 6.44,
          "text": "違う首もセットでのびっくりというかそう"
        },
        {
          "start": 902.199,
          "duration": 5.601,
          "text": "だよねなんかじゃあもっとうんしてく"
        },
        {
          "start": 905.68,
          "duration": 4.64,
          "text": "れって思っちゃうかもなその自分が生徒"
        },
        {
          "start": 907.8,
          "duration": 4.839,
          "text": "だったらなんかじゃあもっと本当にもう"
        },
        {
          "start": 910.32,
          "duration": 4.199,
          "text": "うん悪いやつとかそうもうコンビニ強盗"
        },
        {
          "start": 912.639,
          "duration": 4.56,
          "text": "みたいななんかもう良くないですよ良く"
        },
        {
          "start": 914.519,
          "duration": 5.56,
          "text": "ないけどなんかより悪であってくるみたい"
        },
        {
          "start": 917.199,
          "duration": 5.32,
          "text": "なそうねあそう好調の犯したことがてこと"
        },
        {
          "start": 920.079,
          "duration": 5.12,
          "text": "ねそうなそんなしょしょうもなみたいな"
        },
        {
          "start": 922.519,
          "duration": 4.68,
          "text": "そうなぜこんなことにやっちゃいけない"
        },
        {
          "start": 925.199,
          "duration": 4.801,
          "text": "ことやった教師ってそんな首になってたっ"
        },
        {
          "start": 927.199,
          "duration": 6.401,
          "text": "けってニュース見てるとねなんかね生徒"
        },
        {
          "start": 930.0,
          "duration": 6.04,
          "text": "ぶん殴ったり生徒ときっみたいなでもあの"
        },
        {
          "start": 933.6,
          "duration": 6.32,
          "text": "先生ここでまだ働いてますよみたいなこと"
        },
        {
          "start": 936.04,
          "duration": 7.08,
          "text": "もあるじゃんなんか1回ちょっと休ま休ん"
        },
        {
          "start": 939.92,
          "duration": 5.76,
          "text": "で給料1/0になった後復帰とか聞きます"
        },
        {
          "start": 943.12,
          "duration": 5.44,
          "text": "全然あるよねここはこうだったここはこう"
        },
        {
          "start": 945.68,
          "duration": 5.2,
          "text": "なんだっていうでこれちょっと別のね読売"
        },
        {
          "start": 948.56,
          "duration": 5.48,
          "text": "新聞オンラインのこのこの件に関しての"
        },
        {
          "start": 950.88,
          "duration": 6.12,
          "text": "ニュースなんですけど最後にねこのえ顧問"
        },
        {
          "start": 954.04,
          "duration": 6.479,
          "text": "を務める野球部の部員に繰り返し暴言を"
        },
        {
          "start": 957.0,
          "duration": 7.56,
          "text": "吐いたなどとして私立中学の男性共有をえ"
        },
        {
          "start": 960.519,
          "duration": 6.641,
          "text": "言及1/10え1ヶ月間の朝会処分とした"
        },
        {
          "start": 964.56,
          "duration": 6.36,
          "text": "なんかさらっとなんかおまけみたいに別の"
        },
        {
          "start": 967.16,
          "duration": 5.96,
          "text": "別の人の別の人の言及処分が書いてあるん"
        },
        {
          "start": 970.92,
          "duration": 5.8,
          "text": "ですよなるほどさらっと滑り込ませさ"
        },
        {
          "start": 973.12,
          "duration": 7.719,
          "text": "滑り込みでこれがそのその中学校でそその"
        },
        {
          "start": 976.72,
          "duration": 7.119,
          "text": "人がへええそれは首にはなんないんそれは"
        },
        {
          "start": 980.839,
          "duration": 6.8,
          "text": "101か月コーヒーをちょろまかしたら首"
        },
        {
          "start": 983.839,
          "duration": 4.881,
          "text": "だけど首退職金なし生徒に暴言を入ったら"
        },
        {
          "start": 987.639,
          "duration": 4.64,
          "text": "大丈夫"
        },
        {
          "start": 988.72,
          "duration": 7.559,
          "text": "生徒よりコーヒーの方が価値が"
        },
        {
          "start": 992.279,
          "duration": 7.401,
          "text": "高いコーヒーの方が上なんだ生徒の心より"
        },
        {
          "start": 996.279,
          "duration": 5.281,
          "text": "70円の方が490円未満そういうこと"
        },
        {
          "start": 999.68,
          "duration": 4.24,
          "text": "じゃないと思うけどそうそういうことじゃ"
        },
        {
          "start": 1001.56,
          "duration": 5.0,
          "text": "ないそれはね指導に熱が入っちゃった"
        },
        {
          "start": 1003.92,
          "duration": 6.599,
          "text": "みたいなことなんだろうけどなんかここ"
        },
        {
          "start": 1006.56,
          "duration": 6.0,
          "text": "から読み取れることてはて世の中のなんか"
        },
        {
          "start": 1010.519,
          "duration": 4.68,
          "text": "どうなってるんですかこの中学校どうなっ"
        },
        {
          "start": 1012.56,
          "duration": 5.519,
          "text": "てめちゃくちゃめちゃくちゃめちゃくちゃ"
        },
        {
          "start": 1015.199,
          "duration": 7.2,
          "text": "だよなうんなんかアンバランスさをやっぱ"
        },
        {
          "start": 1018.079,
          "duration": 7.321,
          "text": "感じにはねいられないまやっぱ校長はでも"
        },
        {
          "start": 1022.399,
          "duration": 6.241,
          "text": "向き合う必要ありますよねそのコーヒーを"
        },
        {
          "start": 1025.4,
          "duration": 5.72,
          "text": "多く飲みたかったっていう自分の気持ち"
        },
        {
          "start": 1028.64,
          "duration": 4.64,
          "text": "うんそうねなぜレギュラーじゃいけなかっ"
        },
        {
          "start": 1031.12,
          "duration": 5.679,
          "text": "たんだろうっていううんいや買えばいいの"
        },
        {
          "start": 1033.28,
          "duration": 6.96,
          "text": "よいっぱい飲みたかった70円を払えって"
        },
        {
          "start": 1036.799,
          "duration": 6.081,
          "text": "払えば良かったでもラージを飲みたかった"
        },
        {
          "start": 1040.24,
          "duration": 5.599,
          "text": "というどうしてもレギュラーの値段で味を"
        },
        {
          "start": 1042.88,
          "duration": 5.799,
          "text": "飲みたかったうん飲みたかったとそこを"
        },
        {
          "start": 1045.839,
          "duration": 5.441,
          "text": "やっぱ見つめざるを得ないですからねうん"
        },
        {
          "start": 1048.679,
          "duration": 6.081,
          "text": "1番これからレギュラーとラージについて"
        },
        {
          "start": 1051.28,
          "duration": 5.8,
          "text": "思考していく人に校長先生がなっていって"
        },
        {
          "start": 1054.76,
          "duration": 4.64,
          "text": "そううんうんいつかやっぱレギュラーと"
        },
        {
          "start": 1057.08,
          "duration": 3.24,
          "text": "ラージの境い目みたいなのを発見して"
        },
        {
          "start": 1059.4,
          "duration": 3.56,
          "text": "やっぱ"
        },
        {
          "start": 1060.32,
          "duration": 7.64,
          "text": "ねエウレカ"
        },
        {
          "start": 1062.96,
          "duration": 7.44,
          "text": "と明確決まってのよ明確にここだったと俺"
        },
        {
          "start": 1067.96,
          "duration": 6.52,
          "text": "はこの量だったらレギュラーで満足でき"
        },
        {
          "start": 1070.4,
          "duration": 7.0,
          "text": "たっていうすごい全然反省し人のせいにし"
        },
        {
          "start": 1074.48,
          "duration": 7.52,
          "text": "てめっちゃ工場多分もうコーヒー飲めない"
        },
        {
          "start": 1077.4,
          "duration": 6.6,
          "text": "本当にチョックすぎてねういやすごいわ"
        },
        {
          "start": 1082.0,
          "duration": 4.48,
          "text": "いやこれすごいニュースちょ罪とバツに"
        },
        {
          "start": 1084.0,
          "duration": 5.28,
          "text": "ついて考えさせられるちょっと怒りを"
        },
        {
          "start": 1086.48,
          "duration": 5.92,
          "text": "感じるかも何へのとかじゃないかもしれ"
        },
        {
          "start": 1089.28,
          "duration": 7.04,
          "text": "うん何かね間違ってるのこの世のこの世の"
        },
        {
          "start": 1092.4,
          "duration": 8.04,
          "text": "運用こうなんだていう驚きうんありますね"
        },
        {
          "start": 1096.32,
          "duration": 5.839,
          "text": "そこはねはいというわけなんで今週はこの"
        },
        {
          "start": 1100.44,
          "duration": 4.28,
          "text": "辺ではいはいありがとうございました"
        },
        {
          "start": 1102.159,
          "duration": 2.561,
          "text": "ありがとうございまし"
        },
        {
          "start": 1105.76,
          "duration": 3.0,
          "text": "た"
        }
