        {
          "start": 326.4,
          "duration": 5.799,
          "text": "みたいな終わりだ腹切れっていうんしそう"
        },
        {
          "start": 329.96,
          "duration": 5.239,
          "text": "いうのあるよねそういう人いるよねすぐ"
        },
        {
          "start": 332.199,
          "duration": 7.761,
          "text": "そこにさ行っちゃうっていううんそれで"
        },
        {
          "start": 335.199,
          "duration": 7.361,
          "text": "もう谷川さんは80代80何歳82歳2歳"
        },
        {
          "start": 339.96,
          "duration": 6.72,
          "text": "かだからもうねあもうあんま残されてない"
        },
        {
          "start": 342.56,
          "duration": 6.72,
          "text": "からもう怖いもんな本当にそうよねそう"
        },
        {
          "start": 346.68,
          "duration": 5.4,
          "text": "そうだそういう人追い込んだらまああなる"
        },
        {
          "start": 349.28,
          "duration": 5.6,
          "text": "かとはうん思うんですけど確かに実際"
        },
        {
          "start": 352.08,
          "duration": 5.48,
          "text": "やっぱさ本当そういうお食とかをして"
        },
        {
          "start": 354.88,
          "duration": 6.599,
          "text": "なんかやめて本当精神病んじゃってそう"
        },
        {
          "start": 357.56,
          "duration": 3.919,
          "text": "いうねそういうことに至っちゃう人うん"
        },
        {
          "start": 361.56,
          "duration": 8.6,
          "text": "その攻めとどこまで攻めていいんですか"
        },
        {
          "start": 365.6,
          "duration": 7.8,
          "text": "みたいとこは実あると思うんですて世の中"
        },
        {
          "start": 370.16,
          "duration": 5.68,
          "text": "がそういうもうあいつを攻めろみたいなれ"
        },
        {
          "start": 373.4,
          "duration": 5.28,
          "text": "になったらちょっと耐えられなでそういう"
        },
        {
          "start": 375.84,
          "duration": 5.96,
          "text": "ことになる時もあるもんね謝ったニュース"
        },
        {
          "start": 378.68,
          "duration": 6.56,
          "text": "をメディアがあげちゃってそのために責任"
        },
        {
          "start": 381.8,
          "duration": 6.56,
          "text": "を取らされちゃうみたいなそうそれを経て"
        },
        {
          "start": 385.24,
          "duration": 5.44,
          "text": "82歳のおじいちゃんからもう死ぬだけ"
        },
        {
          "start": 388.36,
          "duration": 6.32,
          "text": "ですようんうん帰って死にますよって言わ"
        },
        {
          "start": 390.68,
          "duration": 6.28,
          "text": "れたらうんちょっともうその後もうなんか"
        },
        {
          "start": 394.68,
          "duration": 4.4,
          "text": "ね言ったらもうこれやべえんじゃね全部"
        },
        {
          "start": 396.96,
          "duration": 5.679,
          "text": "悪いんだからそうねけしからないやつだよ"
        },
        {
          "start": 399.08,
          "duration": 7.48,
          "text": "私はうんなんかもうちょっと覚悟みたいな"
        },
        {
          "start": 402.639,
          "duration": 7.761,
          "text": "のが宿っちゃってるんです良くないその法"
        },
        {
          "start": 406.56,
          "duration": 6.84,
          "text": "は良くないけどなんかもう強すぎるなって"
        },
        {
          "start": 410.4,
          "duration": 5.0,
          "text": "この強いこれはやっぱ強いよなんか謝罪"
        },
        {
          "start": 413.4,
          "duration": 5.6,
          "text": "バグなんですよ"
        },
        {
          "start": 415.4,
          "duration": 5.56,
          "text": "なんか謝罪というものの仕組みの脆弱性な"
        },
        {
          "start": 419.0,
          "duration": 5.599,
          "text": "んですよそうなんだよねッされてるよね"
        },
        {
          "start": 420.96,
          "duration": 7.6,
          "text": "もう謝罪をうん完全に謝ってるもん私が"
        },
        {
          "start": 424.599,
          "duration": 7.04,
          "text": "悪い頭も下げてません本当に思ってるよう"
        },
        {
          "start": 428.56,
          "duration": 7.039,
          "text": "には見えないけど言葉では言ってるから言"
        },
        {
          "start": 431.639,
          "duration": 6.361,
          "text": "しやめてるし実確確だからてめえいや"
        },
        {
          "start": 435.599,
          "duration": 6.081,
          "text": "ふざけんなよみたいなね言ってるだけだろ"
        },
        {
          "start": 438.0,
          "duration": 6.36,
          "text": "いややめたしじゃ死ぬか次はもう死ぬに"
        },
        {
          "start": 441.68,
          "duration": 6.079,
          "text": "行くぞそれ言われたらもうさ終わりじゃ"
        },
        {
          "start": 444.36,
          "duration": 6.76,
          "text": "ないです謝罪のハイスコアバグハイスコア"
        },
        {
          "start": 447.759,
          "duration": 6.961,
          "text": "出しすぎ表記バグってるだもう自分が"
        },
        {
          "start": 451.12,
          "duration": 7.759,
          "text": "終わることによっても何かをもう守り"
        },
        {
          "start": 454.72,
          "duration": 6.72,
          "text": "ながらもうそうね蓋をして最後までもそれ"
        },
        {
          "start": 458.879,
          "duration": 5.921,
          "text": "で行くってもう決めちゃったからねもうね"
        },
        {
          "start": 461.44,
          "duration": 5.92,
          "text": "そうですよね人が人に謝罪をしてほしいっ"
        },
        {
          "start": 464.8,
          "duration": 5.04,
          "text": "て時に一体何を求めてたんだっけて"
        },
        {
          "start": 467.36,
          "duration": 5.399,
          "text": "ちょっとあなるほどポカンとしてしまう"
        },
        {
          "start": 469.84,
          "duration": 5.28,
          "text": "部分すら感じこの人に何をさせたかったん"
        },
        {
          "start": 472.759,
          "duration": 4.801,
          "text": "だっけみたいなところに行ってしまううん"
        },
        {
          "start": 475.12,
          "duration": 6.32,
          "text": "いや強いねあれは確かになんか中途半端に"
        },
        {
          "start": 477.56,
          "duration": 6.919,
          "text": "さ言葉とかはうんすごい丁寧だけどなんか"
        },
        {
          "start": 481.44,
          "duration": 6.199,
          "text": "全然話さない説明しないし明かさないし"
        },
        {
          "start": 484.479,
          "duration": 4.84,
          "text": "なんか本当はこいつ自分のこともそんな"
        },
        {
          "start": 487.639,
          "duration": 4.081,
          "text": "悪いと思ってないだろうなみたいになっ"
        },
        {
          "start": 489.319,
          "duration": 5.481,
          "text": "たらなんかみんなもっと怒りが湧くという"
        },
        {
          "start": 491.72,
          "duration": 6.159,
          "text": "かいやちゃんとやれよみたいな説明責に"
        },
        {
          "start": 494.8,
          "duration": 6.399,
          "text": "果たせてなるんだけどほアクセルべた踏み"
        },
        {
          "start": 497.879,
          "duration": 5.6,
          "text": "のあのシせられたらそこまで踏み込まれ"
        },
        {
          "start": 501.199,
          "duration": 4.081,
          "text": "たらですよね逆ちょちょっとブレーキ踏ん"
        },
        {
          "start": 503.479,
          "duration": 5.321,
          "text": "でくるみたいななんか気持ちになって"
        },
        {
          "start": 505.28,
          "duration": 6.72,
          "text": "なんかやっぱもうこれだから赤木のの"
        },
        {
          "start": 508.8,
          "duration": 5.76,
          "text": "にうんそうねだからチキンレースで中途"
        },
        {
          "start": 512.0,
          "duration": 5.44,
          "text": "半端にブレーキを踏んだら危ない危ないと"
        },
        {
          "start": 514.56,
          "duration": 6.24,
          "text": "いうねもうアクセル全開でも崖をもう全速"
        },
        {
          "start": 517.44,
          "duration": 5.959,
          "text": "力で行けば元勝地帯を乗り切って綺麗に海"
        },
        {
          "start": 520.8,
          "duration": 6.56,
          "text": "に落ちれ落ちれというそれをやっぱね"
        },
        {
          "start": 523.399,
          "duration": 7.481,
          "text": "まさに谷川さんはここやっだからそうよね"
        },
        {
          "start": 527.36,
          "duration": 7.76,
          "text": "もうこいつ命が惜しくないのかっても思わ"
        },
        {
          "start": 530.88,
          "duration": 8.88,
          "text": "せたら勝ちみたいね板垣介先生が10何年"
        },
        {
          "start": 535.12,
          "duration": 8.279,
          "text": "か前にあの土ていうはいあああったね"
        },
        {
          "start": 539.76,
          "duration": 6.28,
          "text": "の漫画をま作が別ですけど確か連載してて"
        },
        {
          "start": 543.399,
          "duration": 6.241,
          "text": "それも謝罪がテーマなんですよね謝罪は"
        },
        {
          "start": 546.04,
          "duration": 4.76,
          "text": "やりすぎると暴力として通用するみたい"
        },
        {
          "start": 549.64,
          "duration": 3.56,
          "text": "そう"
        },
        {
          "start": 550.8,
          "duration": 4.88,
          "text": "いうなんか謝罪のプロみたいなのが"
        },
        {
          "start": 553.2,
          "duration": 6.319,
          "text": "いっぱい出てくるんですね確かそん中で"
        },
        {
          "start": 555.68,
          "duration": 6.2,
          "text": "すごい覚えてるのでなんか電池メーカーの"
        },
        {
          "start": 559.519,
          "duration": 4.721,
          "text": "その中間管理職みたいになってこの電池"
        },
        {
          "start": 561.88,
          "duration": 5.639,
          "text": "不良品だったよどうしてくれるんだね"
        },
        {
          "start": 564.24,
          "duration": 6.719,
          "text": "みたいなったすいませんて言いながらその"
        },
        {
          "start": 567.519,
          "duration": 8.56,
          "text": "単位電池をうんで砕け"
        },
        {
          "start": 570.959,
          "duration": 8.801,
          "text": "始ボリボリ面白そ謝罪じゃねえだ気候だろ"
        },
        {
          "start": 576.079,
          "duration": 6.32,
          "text": "たそれはでもそれやったら終わりなん全部"
        },
        {
          "start": 579.76,
          "duration": 6.12,
          "text": "おしまいだでもそのお前がやらせたんだ"
        },
        {
          "start": 582.399,
          "duration": 7.56,
          "text": "よっていうことを相手に俺はもう電池を"
        },
        {
          "start": 585.88,
          "duration": 7.44,
          "text": "食いましたあなたはっていうもう相手に"
        },
        {
          "start": 589.959,
          "duration": 6.081,
          "text": "もうね攻撃してるのと同じことになってる"
        },
        {
          "start": 593.32,
          "duration": 6.4,
          "text": "うんここまで行かれるとでもなんかもう"
        },
        {
          "start": 596.04,
          "duration": 7.72,
          "text": "これをさ結構なんかこれやった時ちょっと"
        },
        {
          "start": 599.72,
          "duration": 7.359,
          "text": "あっぱれ的な声を言ってる人もいたんす"
        },
        {
          "start": 603.76,
          "duration": 7.319,
          "text": "よいやあっぱれもやっぱおかしいよでは"
        },
        {
          "start": 607.079,
          "duration": 8.401,
          "text": "ないまままなんバグ技だかそうねそうだ"
        },
        {
          "start": 611.079,
          "duration": 7.32,
          "text": "そうだわバグを見て喜んでる確そうGTA"
        },
        {
          "start": 615.48,
          "duration": 5.28,
          "text": "のかチート集みたいなてなんかゲラゲラ"
        },
        {
          "start": 618.399,
          "duration": 4.841,
          "text": "笑ってるみたいな気持ちでチートの面白さ"
        },
        {
          "start": 620.76,
          "duration": 5.12,
          "text": "でしかないから本来はこれこうじゃないよ"
        },
        {
          "start": 623.24,
          "duration": 6.12,
          "text": "なっていう来は絶対ダメなんですよそんな"
        },
        {
          "start": 625.88,
          "duration": 6.6,
          "text": "こと見の場であんなことしたらなんか"
        },
        {
          "start": 629.36,
          "duration": 6.76,
          "text": "やっぱそうあっぱれてなんかこう守備一貫"
        },
        {
          "start": 632.48,
          "duration": 6.28,
          "text": "した態度に対してなんかよくやったんじゃ"
        },
        {
          "start": 636.12,
          "duration": 4.88,
          "text": "ないけどま潔よいとかなんかそういう"
        },
        {
          "start": 638.76,
          "duration": 5.24,
          "text": "気持ちもちょっと確かに湧くんだけど"
        },
        {
          "start": 641.0,
          "duration": 4.92,
          "text": "なんかそれともちゃんと戦わないといけ"
        },
        {
          "start": 644.0,
          "duration": 5.48,
          "text": "ないんだろうなとはなんか感じましたね"
        },
        {
          "start": 645.92,
          "duration": 6.88,
          "text": "やっぱねま確かにあとそんなにお金って"
        },
        {
          "start": 649.48,
          "duration": 5.12,
          "text": "いるんですかねやっぱりま実際実際やって"
        },
        {
          "start": 652.8,
          "duration": 4.44,
          "text": "たってことでいいんですかあのまそれは"
        },
        {
          "start": 654.6,
          "duration": 6.4,
          "text": "もう認めてますまあそうですよねキック"
        },
        {
          "start": 657.24,
          "duration": 7.56,
          "text": "バックを受けてたというもう大臣なみのお"
        },
        {
          "start": 661.0,
          "duration": 7.839,
          "text": "金をうんあの集めたかったみたいなことを"
        },
        {
          "start": 664.8,
          "duration": 7.44,
          "text": "ええま結局だから政治家でなんかね公共事"
        },
        {
          "start": 668.839,
          "duration": 7.0,
          "text": "事業を地元に引っ張ってうんまその地元の"
        },
        {
          "start": 672.24,
          "duration": 6.52,
          "text": "会社とかをこうね利益にさせるみたいな"
        },
        {
          "start": 675.839,
          "duration": 5.081,
          "text": "長崎県の課題をそれで処理したかった"
        },
        {
          "start": 678.76,
          "duration": 5.04,
          "text": "みたいなことは言ってるんですけどまあ"
        },
        {
          "start": 680.92,
          "duration": 5.0,
          "text": "まあうん悪かったと反省してるとで"
        },
        {
          "start": 683.8,
          "duration": 5.719,
          "text": "生まれ変わったらどんな政治家になりたい"
        },
        {
          "start": 685.92,
          "duration": 7.08,
          "text": "かと聞かれたらうんすごいこと聞くななる"
        },
        {
          "start": 689.519,
          "duration": 5.0,
          "text": "ことはないすごい答えだないやすごいよ"
        },
        {
          "start": 693.0,
          "duration": 4.36,
          "text": "やっぱ"
        },
        {
          "start": 694.519,
          "duration": 6.32,
          "text": "すごいパンチラインがすごいチライ"
        },
        {
          "start": 697.36,
          "duration": 6.36,
          "text": "すごかったすねやっぱね頭の下げ方が足り"
        },
        {
          "start": 700.839,
          "duration": 5.921,
          "text": "ないんですかとかフルコースじゃやっぱ"
        },
        {
          "start": 703.72,
          "duration": 7.16,
          "text": "すごいのよね1個投げたらやっぱ10にし"
        },
        {
          "start": 706.76,
          "duration": 6.6,
          "text": "て返してくるすごいけどねすこういうとこ"
        },
        {
          "start": 710.88,
          "duration": 5.12,
          "text": "も含めてやっぱ政治家っていういやすごい"
        },
        {
          "start": 713.36,
          "duration": 5.4,
          "text": "すですそういでもやっぱリアリストなん"
        },
        {
          "start": 716.0,
          "duration": 8.44,
          "text": "でしょうね本当徹底した生まれ変わるこ"
        },
        {
          "start": 718.76,
          "duration": 8.8,
          "text": "うんはないとかもう徹底して金減利益地元"
        },
        {
          "start": 724.44,
          "duration": 5.76,
          "text": "に何か仕事引っ張るとかそううんもう完全"
        },
        {
          "start": 727.56,
          "duration": 5.92,
          "text": "にそれにもう思考してる人なんでしょうね"
        },
        {
          "start": 730.2,
          "duration": 5.4,
          "text": "もうねそれしか考えてないというかそし"
        },
        {
          "start": 733.48,
          "duration": 4.719,
          "text": "たらもう謝罪もああいうことになるわけ"
        },
        {
          "start": 735.6,
          "duration": 5.84,
          "text": "ですよねシステムとしての謝罪っていう"
        },
        {
          "start": 738.199,
          "duration": 9.681,
          "text": "ものをもう1回倒したらああなってという"
        },
        {
          "start": 741.44,
          "duration": 9.6,
          "text": "かっうんいやすいがそう強い謝罪でしたね"
        },
        {
          "start": 747.88,
          "duration": 7.319,
          "text": "強い罪に負けないにはどうしたらいどうし"
        },
        {
          "start": 751.04,
          "duration": 7.08,
          "text": "たらどうあれを確あれ飛び出し何をやっぱ"
        },
        {
          "start": 755.199,
          "duration": 6.64,
          "text": "打てばいいのか浄化なやっぱいやもう"
        },
        {
          "start": 758.12,
          "duration": 5.399,
          "text": "さらに強い追求さらに強い追求そうですよ"
        },
        {
          "start": 761.839,
          "duration": 5.321,
          "text": "死ねって言ってるんですかって言われ"
        },
        {
          "start": 763.519,
          "duration": 6.201,
          "text": "たらそうですよあ強いそうですすてもう"
        },
        {
          "start": 767.16,
          "duration": 4.64,
          "text": "全力で返すしかないのかもしれない"
        },
        {
          "start": 769.72,
          "duration": 4.28,
          "text": "なるほどそうかもうそれしかない命の"
        },
        {
          "start": 771.8,
          "duration": 6.36,
          "text": "やり取りなるしかもうないそれってほと"
        },
        {
          "start": 774.0,
          "duration": 6.839,
          "text": "武士の世界そうね別に命のやり取りをたい"
        },
        {
          "start": 778.16,
          "duration": 2.679,
          "text": "わじゃ"
        },
        {
          "start": 781.399,
          "duration": 7.12,
          "text": "だのう"
        },
        {
          "start": 784.519,
          "duration": 7.281,
          "text": "されてるっていうのあのやっぱつかなきゃ"
        },
        {
          "start": 788.519,
          "duration": 6.56,
          "text": "いけないよねそういう話はしてないです"
        },
        {
          "start": 791.8,
          "duration": 6.039,
          "text": "ないと思う通じないのかなもう喋りたくな"
        },
        {
          "start": 795.079,
          "duration": 5.241,
          "text": "いって言ってるんだった話はそらされてる"
        },
        {
          "start": 797.839,
          "duration": 5.12,
          "text": "わけですよ情報を出せって言ってんのに"
        },
        {
          "start": 800.32,
          "duration": 4.519,
          "text": "ごめんなさいって言ってるじゃないですか"
        },
        {
          "start": 802.959,
          "duration": 4.201,
          "text": "ディスコミュニケーションなのがなんと"
        },
        {
          "start": 804.839,
          "duration": 5.481,
          "text": "なくごまかされてるじてないよねこれ"
        },
        {
          "start": 807.16,
          "duration": 7.119,
          "text": "ちょっとの"
        },
        {
          "start": 810.32,
          "duration": 7.519,
          "text": "と論みたいなそうねずらしてずらして相手"
        },
        {
          "start": 814.279,
          "duration": 6.041,
          "text": "にはしか答えずにこうそう実は噛み合って"
        },
        {
          "start": 817.839,
          "duration": 4.8,
          "text": "ないみたいこれを許してると全部そこで"
        },
        {
          "start": 820.32,
          "duration": 5.24,
          "text": "終わっちゃうからなんとかしたいんですよ"
        },
        {
          "start": 822.639,
          "duration": 5.841,
          "text": "その極論だけ言ってるやつをもうちょっと"
        },
        {
          "start": 825.56,
          "duration": 5.88,
          "text": "こう極論を下げて怖いもんなしのやつが"
        },
        {
          "start": 828.48,
          "duration": 6.2,
          "text": "勝つ社会にそうなっちゃうからでも実際も"
        },
        {
          "start": 831.44,
          "duration": 5.92,
          "text": "やめてるからさあもうやめたんでって言わ"
        },
        {
          "start": 834.68,
          "duration": 7.12,
          "text": "れたらそれもどうしようもないんそれも"
        },
        {
          "start": 837.36,
          "duration": 9.039,
          "text": "どうしじゃ今の姿お孫さんが見たらどう"
        },
        {
          "start": 841.8,
          "duration": 7.56,
          "text": "思うんですかみたいないや関係ない係そう"
        },
        {
          "start": 846.399,
          "duration": 9.0,
          "text": "いうでしょ死ぬしかない孫連れてきたらお"
        },
        {
          "start": 849.36,
          "duration": 10.64,
          "text": "じいちゃん話しててああ孫の眉間に銃とか"
        },
        {
          "start": 855.399,
          "duration": 8.081,
          "text": "あってて強い強い追求じゃねえなんかもう"
        },
        {
          "start": 860.0,
          "duration": 7.68,
          "text": "そういう情とかじゃいけないのもっとああ"
        },
        {
          "start": 863.48,
          "duration": 7.68,
          "text": "確かにねでもそれはやる側の方が覚悟いり"
        },
        {
          "start": 867.68,
          "duration": 6.44,
          "text": "ますからねうなんかやっぱずるいよこう"
        },
        {
          "start": 871.16,
          "duration": 6.119,
          "text": "極論で逃げきるっていうのさそうねうん"
        },
        {
          "start": 874.12,
          "duration": 5.959,
          "text": "やっぱそういう逃げ方はなるべくねしない"
        },
        {
          "start": 877.279,
          "duration": 5.201,
          "text": "ようにしていきたいですけどやっぱおじい"
        },
        {
          "start": 880.079,
          "duration": 5.041,
          "text": "ちゃんほど多いよね多いねなんか結構"
        },
        {
          "start": 882.48,
          "duration": 7.0,
          "text": "やっぱその見てま世代とかもあんのかも"
        },
        {
          "start": 885.12,
          "duration": 8.68,
          "text": "しれないけどやっぱうんすごいさうん切れ"
        },
        {
          "start": 889.48,
          "duration": 9.279,
          "text": "謝罪切れ謝罪切れ謝罪あれすごいああL"
        },
        {
          "start": 893.8,
          "duration": 8.08,
          "text": "謝罪綺麗謝罪そんな謝罪で大夫大丈夫か"
        },
        {
          "start": 898.759,
          "duration": 7.08,
          "text": "ダメなんだよああいやだからもう本当自分"
        },
        {
          "start": 901.88,
          "duration": 6.36,
          "text": "の時はこういうね極論を本当口走らない"
        },
        {
          "start": 905.839,
          "duration": 5.481,
          "text": "ようにさうんうんうんうんイラっとしても"
        },
        {
          "start": 908.24,
          "duration": 5.8,
          "text": "やっぱ曲に行かずにどんだけ踏みとまれる"
        },
        {
          "start": 911.32,
          "duration": 6.199,
          "text": "かっていうそうねことをしたいですけど"
        },
        {
          "start": 914.04,
          "duration": 6.28,
          "text": "そうねやっぱそういう極論やると失うも"
        },
        {
          "start": 917.519,
          "duration": 5.801,
          "text": "のっていうのはねありますから信用いや"
        },
        {
          "start": 920.32,
          "duration": 5.519,
          "text": "そうそう対局的目はどんどん失うわうん逆"
        },
        {
          "start": 923.32,
          "duration": 6.079,
          "text": "に言うと80過ぎたらもうそれもなくなる"
        },
        {
          "start": 925.839,
          "duration": 6.201,
          "text": "から結局これが最適会にはなっていんそう"
        },
        {
          "start": 929.399,
          "duration": 4.92,
          "text": "あの人にとってはこれが最適な手法だった"
        },
        {
          "start": 932.04,
          "duration": 5.4,
          "text": "という守るべきだってもう政治家としての"
        },
        {
          "start": 934.319,
          "duration": 6.241,
          "text": "あれもないしうんあとはもう強謝罪で乗り"
        },
        {
          "start": 937.44,
          "duration": 5.48,
          "text": "強謝罪でもう乗り切ってすごいなそれもう"
        },
        {
          "start": 940.56,
          "duration": 4.959,
          "text": "田舎に帰ろうという気持ちだけこれの本当"
        },
        {
          "start": 942.92,
          "duration": 3.599,
          "text": "攻略法しってる人がいたらちょっと教えて"
        },
        {
          "start": 945.519,
          "duration": 4.88,
          "text": "いただき"
        },
        {
          "start": 946.519,
          "duration": 7.56,
          "text": "たいす難しいなんとかしたいよねこれは急"
        },
        {
          "start": 950.399,
          "duration": 6.44,
          "text": "にトピなことを言うっていうのはえあの人"
        },
        {
          "start": 954.079,
          "duration": 7.401,
          "text": "がなんかああいうバーって強謝罪してる間"
        },
        {
          "start": 956.839,
          "duration": 6.881,
          "text": "にイゴパフって好きですかて急にトピな"
        },
        {
          "start": 961.48,
          "duration": 6.359,
          "text": "こと言ってそのフリーズさ"
        },
        {
          "start": 963.72,
          "duration": 6.88,
          "text": "せるバグにバグをつけてうん今日をつくっ"
        },
        {
          "start": 967.839,
          "duration": 8.201,
          "text": "ていうあ確かに1回クール"
        },
        {
          "start": 970.6,
          "duration": 6.4,
          "text": "ダウン好きでああはい好きです何があった"
        },
        {
          "start": 976.04,
          "duration": 4.88,
          "text": "んです"
        },
        {
          "start": 977.0,
          "duration": 6.56,
          "text": "かなんかちょっと熱を1回取ってなるほど"
        },
        {
          "start": 980.92,
          "duration": 5.039,
          "text": "なるほどねうんなんかあれっていう気持ち"
        },
        {
          "start": 983.56,
          "duration": 5.8,
          "text": "にさせるっていうのはなんかいいかもいい"
        },
        {
          "start": 985.959,
          "duration": 6.201,
          "text": "かももうそういう変な質問するていう"
        },
        {
          "start": 989.36,
          "duration": 6.479,
          "text": "あえてああいいかもあうんでちょっと油断"
        },
        {
          "start": 992.16,
          "duration": 7.919,
          "text": "というか心に隙を持たせたらなんかポロっ"
        },
        {
          "start": 995.839,
          "duration": 7.56,
          "text": "と出ることがあるんじゃないかっていう"
        },
        {
          "start": 1000.079,
          "duration": 5.76,
          "text": "猫魂1回誰かやってほしい猫魂をそう"
        },
        {
          "start": 1003.399,
          "duration": 4.401,
          "text": "やっぱそうな組み合っちゃいけないんだ組"
        },
        {
          "start": 1005.839,
          "duration": 5.201,
          "text": "がっぷりよつじゃだがっぷりよつじゃも"
        },
        {
          "start": 1007.8,
          "duration": 5.24,
          "text": "勝てないんでやっぱ絡めてからなるほど"
        },
        {
          "start": 1011.04,
          "duration": 3.56,
          "text": "行った方がいいんじゃないかセクシー"
        },
        {
          "start": 1013.04,
          "duration": 7.479,
          "text": "コマンドじゃない"
        },
        {
          "start": 1014.6,
          "duration": 8.56,
          "text": "セクシ確かそうだ確かにそうだあそうかも"
        },
        {
          "start": 1020.519,
          "duration": 5.841,
          "text": "うんマサさんには確か通用しないだろうな"
        },
        {
          "start": 1023.16,
          "duration": 7.039,
          "text": "通用罪用しないよ通用謝罪はす変なポーズ"
        },
        {
          "start": 1026.36,
          "duration": 7.88,
          "text": "とかしてこいつななんだみたいな確やっぱ"
        },
        {
          "start": 1030.199,
          "duration": 6.0,
          "text": "よりあいつクレイジーに上回るかの勝負に"
        },
        {
          "start": 1034.24,
          "duration": 5.12,
          "text": "なっちゃうんだそっちでもう行くしかない"
        },
        {
          "start": 1036.199,
          "duration": 6.801,
          "text": "かもねやっぱうんうんだからさっきの"
        },
        {
          "start": 1039.36,
          "duration": 5.439,
          "text": "赤ちゃんはいいと思います俺ああ会見で"
        },
        {
          "start": 1043.0,
          "duration": 3.439,
          "text": "そういう話してないですよみたいないや"
        },
        {
          "start": 1044.799,
          "duration": 5.281,
          "text": "じゃなんでどうやって席に取るんですか"
        },
        {
          "start": 1046.439,
          "duration": 5.521,
          "text": "死ぬんですかうんうんええええ"
        },
        {
          "start": 1050.08,
          "duration": 4.0,
          "text": "ええ"
        },
        {
          "start": 1051.96,
          "duration": 5.92,
          "text": "赤ちゃん"
        },
        {
          "start": 1054.08,
          "duration": 8.16,
          "text": "えなんでこいつ赤ちゃんを急"
        },
        {
          "start": 1057.88,
          "duration": 8.039,
          "text": "に面白い面白いだけじゃんそのおば面白く"
        },
        {
          "start": 1062.24,
          "duration": 7.04,
          "text": "なっていくよくはならない混沌が増えた"
        },
        {
          "start": 1065.919,
          "duration": 5.841,
          "text": "だけですそれそんぐらいしてやんないとも"
        },
        {
          "start": 1069.28,
          "duration": 5.2,
          "text": "こんなやつらに全頭な方法じゃ勝てないん"
        },
        {
          "start": 1071.76,
          "duration": 6.0,
          "text": "ですにねやっぱ謝罪の場に限らず世の中ね"
        },
        {
          "start": 1074.48,
          "duration": 6.88,
          "text": "狂い毒なんですよ今の世界狂い毒がばれて"
        },
        {
          "start": 1077.76,
          "duration": 6.96,
          "text": "きたらやばいですようだからそれをね誰か"
        },
        {
          "start": 1081.36,
          "duration": 5.92,
          "text": "がやっぱ食い止めなきゃいけないてうん"
        },
        {
          "start": 1084.72,
          "duration": 4.64,
          "text": "いやこれ本当に難しい問題ですよ戦い"
        },
        {
          "start": 1087.28,
          "duration": 4.36,
          "text": "ましょうみんなではいうんというわけなん"
        },
        {
          "start": 1089.36,
          "duration": 5.4,
          "text": "で今週はこんな辺ではいありがとうござい"
        },
        {
          "start": 1091.64,
          "duration": 6.12,
          "text": "ましたありがとうございございまし"
        },
        {
          "start": 1094.76,
          "duration": 3.0,
          "text": "た"
        }
