        {
          "start": 1128.36,
          "duration": 5.12,
          "text": "なんだよなだからそれをその大切り"
        },
        {
          "start": 1130.84,
          "duration": 4.48,
          "text": "レビューで滑ってるよって言われること僕"
        },
        {
          "start": 1133.48,
          "duration": 4.319,
          "text": "は悪いことじゃないんじゃないかとうん"
        },
        {
          "start": 1135.32,
          "duration": 5.239,
          "text": "うんうんそうですねだ書いてもいいし怒ら"
        },
        {
          "start": 1137.799,
          "duration": 5.841,
          "text": "れてももいいんですようんうんそれ不の水"
        },
        {
          "start": 1140.559,
          "duration": 7.641,
          "text": "としてそうですね次につなげればいい次の"
        },
        {
          "start": 1143.64,
          "duration": 8.12,
          "text": "あなたの表現に確か確かにひなひユもは"
        },
        {
          "start": 1148.2,
          "duration": 6.719,
          "text": "あのひなかひどもが泣いている泣いてい"
        },
        {
          "start": 1151.76,
          "duration": 6.08,
          "text": "ぴよぴよとそうですねレビューラで泣いて"
        },
        {
          "start": 1154.919,
          "duration": 6.081,
          "text": "いる泣いていると思おうよとそういうのも"
        },
        {
          "start": 1157.84,
          "duration": 7.16,
          "text": "許容し確かにそれも本当そうですそれを"
        },
        {
          "start": 1161.0,
          "duration": 8.52,
          "text": "もう選択と集中の精神でまびいて底に"
        },
        {
          "start": 1165.0,
          "duration": 8.4,
          "text": "落とすのかそれとも救い上げて育てるのか"
        },
        {
          "start": 1169.52,
          "duration": 7.36,
          "text": "いうねうんああそうなんでマビまびこなん"
        },
        {
          "start": 1173.4,
          "duration": 6.24,
          "text": "でまトレザーも結局まく川じゃねえか"
        },
        {
          "start": 1176.88,
          "duration": 5.48,
          "text": "ユートピアの側じゃね育てた方がいいん"
        },
        {
          "start": 1179.64,
          "duration": 5.519,
          "text": "じゃないかなとは思いますけどねれ山が"
        },
        {
          "start": 1182.36,
          "duration": 5.72,
          "text": "一番こういうのにむかついてるついては"
        },
        {
          "start": 1185.159,
          "duration": 6.841,
          "text": "ない俺が俺がちょっと行ったからバランス"
        },
        {
          "start": 1188.08,
          "duration": 6.599,
          "text": "取るために急にブレーキ踏み上がったけど"
        },
        {
          "start": 1192.0,
          "duration": 5.799,
          "text": "こいつはやっぱもう本当確かにでもそれザ"
        },
        {
          "start": 1194.679,
          "duration": 8.281,
          "text": "が本当に思ってることを言ったら今こん"
        },
        {
          "start": 1197.799,
          "duration": 7.321,
          "text": "もう地獄がいやいや1つの地獄が生まれて"
        },
        {
          "start": 1202.96,
          "duration": 4.88,
          "text": "言葉っていうのは恐ろしい確かにそれは"
        },
        {
          "start": 1205.12,
          "duration": 5.919,
          "text": "そうかもそれはそうかもしんないうんうん"
        },
        {
          "start": 1207.84,
          "duration": 6.76,
          "text": "いやいやいやまあね私はリプライで画像"
        },
        {
          "start": 1211.039,
          "duration": 6.76,
          "text": "ついてるやつは問答無用で引きおいてうん"
        },
        {
          "start": 1214.6,
          "duration": 7.199,
          "text": "もう厳しいなこいつの方が厳しいかも非"
        },
        {
          "start": 1217.799,
          "duration": 6.321,
          "text": "表示にするだけですそこ非表示にされたよ"
        },
        {
          "start": 1221.799,
          "duration": 5.161,
          "text": "なんでだろう考えてみようっていう"
        },
        {
          "start": 1224.12,
          "duration": 5.2,
          "text": "メッセージを今私は送り続けてるえミュー"
        },
        {
          "start": 1226.96,
          "duration": 5.12,
          "text": "トってことミュート違いますあのリプライ"
        },
        {
          "start": 1229.32,
          "duration": 5.239,
          "text": "として表示されなくてなんか右下に"
        },
        {
          "start": 1232.08,
          "duration": 5.479,
          "text": "ちっちゃく出てるボタンを押さないとそれ"
        },
        {
          "start": 1234.559,
          "duration": 5.921,
          "text": "が出ないんです隔離みたいになるなるほど"
        },
        {
          "start": 1237.559,
          "duration": 6.921,
          "text": "プイそ相手も気づくの相手も気づきますあ"
        },
        {
          "start": 1240.48,
          "duration": 6.92,
          "text": "気づくそれえめっちゃ選別選別してという"
        },
        {
          "start": 1244.48,
          "duration": 6.6,
          "text": "教育うんなんか"
        },
        {
          "start": 1247.4,
          "duration": 5.84,
          "text": "そのうんうんでもそこでこさに何かを言っ"
        },
        {
          "start": 1251.08,
          "duration": 5.52,
          "text": "たりブロックをしたりするわけじゃない"
        },
        {
          "start": 1253.24,
          "duration": 4.91,
          "text": "すごいなんか特定の条件を満たし人たち"
        },
        {
          "start": 1256.6,
          "duration": 3.28,
          "text": "だけが行く部屋を用うん"
        },
        {
          "start": 1258.15,
          "duration": 4.529,
          "text": "[笑い]"
        },
        {
          "start": 1259.88,
          "duration": 4.919,
          "text": "なぜそうなるかは各自でそれを言葉にする"
        },
        {
          "start": 1262.679,
          "duration": 5.161,
          "text": "とそれは嘘なんですよなるほどそれは確か"
        },
        {
          "start": 1264.799,
          "duration": 5.561,
          "text": "になああなるほどねあのコーチングだ"
        },
        {
          "start": 1267.84,
          "duration": 5.88,
          "text": "ティーチング答えを言っちゃうじゃなくて"
        },
        {
          "start": 1270.36,
          "duration": 6.12,
          "text": "ほら隔離されたよほらどうしてかなんで"
        },
        {
          "start": 1273.72,
          "duration": 5.6,
          "text": "でしょうてみようねなぜなぜご過剰をやっ"
        },
        {
          "start": 1276.48,
          "duration": 6.319,
          "text": "ていただくあすごいですそういうことか"
        },
        {
          "start": 1279.32,
          "duration": 6.4,
          "text": "なっていう厳しい世界だないや厳しい世界"
        },
        {
          "start": 1282.799,
          "duration": 6.841,
          "text": "ですよね本にうんいやでも人はでもそう"
        },
        {
          "start": 1285.72,
          "duration": 6.839,
          "text": "やって大きくなるからうんねうん中には"
        },
        {
          "start": 1289.64,
          "duration": 5.72,
          "text": "そのいるはずなんですよその大切り"
        },
        {
          "start": 1292.559,
          "duration": 5.641,
          "text": "レビューをしてるような人の中にもいつか"
        },
        {
          "start": 1295.36,
          "duration": 6.48,
          "text": "待機万正をなすようなあいると思いますよ"
        },
        {
          "start": 1298.2,
          "duration": 8.32,
          "text": "それは全そていうのがねだからそこを制限"
        },
        {
          "start": 1301.84,
          "duration": 8.36,
          "text": "するのじゃなくてやはりこうね冷たい視線"
        },
        {
          "start": 1306.52,
          "duration": 7.08,
          "text": "という名の温かい情を誰かが注がなけれと"
        },
        {
          "start": 1310.2,
          "duration": 6.16,
          "text": "いう温それは違うぞの目を相手もいいこと"
        },
        {
          "start": 1313.6,
          "duration": 5.36,
          "text": "言ったねいいこと言ったま確かにその厳し"
        },
        {
          "start": 1316.36,
          "duration": 5.799,
          "text": "さみたいなものもどっかにいりますもんね"
        },
        {
          "start": 1318.96,
          "duration": 6.079,
          "text": "それはねやっぱなんか当たり障りないこと"
        },
        {
          "start": 1322.159,
          "duration": 5.321,
          "text": "を言うだけがやっぱ優しさではないうん"
        },
        {
          "start": 1325.039,
          "duration": 4.721,
          "text": "うんうんそれはそうだと思うようんだから"
        },
        {
          "start": 1327.48,
          "duration": 7.12,
          "text": "もうはっきりとやっぱもう言うべきやんす"
        },
        {
          "start": 1329.76,
          "duration": 8.2,
          "text": "その本当にうんルールだもうその彼女に"
        },
        {
          "start": 1334.6,
          "duration": 6.16,
          "text": "振られたこのゲーム0点はもうダメだと"
        },
        {
          "start": 1337.96,
          "duration": 5.28,
          "text": "うんうんうん面白くないからやめてほし"
        },
        {
          "start": 1340.76,
          "duration": 5.84,
          "text": "いってそううんうんはっきりやっぱ伝える"
        },
        {
          "start": 1343.24,
          "duration": 6.4,
          "text": "ことも大事なんですそれも確かに大事あと"
        },
        {
          "start": 1346.6,
          "duration": 5.4,
          "text": "やっぱそういう初犯かどかやっぱオもさ"
        },
        {
          "start": 1349.64,
          "duration": 6.56,
          "text": "あのやっぱめちゃくちゃ襲いまくってた"
        },
        {
          "start": 1352.0,
          "duration": 8.52,
          "text": "わけねだ一等襲ってただけだったらあんな"
        },
        {
          "start": 1356.2,
          "duration": 6.92,
          "text": "に危険しはされなかった確だからおみたい"
        },
        {
          "start": 1360.52,
          "duration": 5.08,
          "text": "にもう手当たり次第にレビューを送り"
        },
        {
          "start": 1363.12,
          "duration": 5.919,
          "text": "まくって大切りレビューを送りまくってる"
        },
        {
          "start": 1365.6,
          "duration": 7.0,
          "text": "やつていうのはもうどっか壊れちゃって"
        },
        {
          "start": 1369.039,
          "duration": 6.88,
          "text": "壊れでそこのやっぱ問題はあるとまだ初版"
        },
        {
          "start": 1372.6,
          "duration": 5.8,
          "text": "というかあの軽い気持ちでね真似してみて"
        },
        {
          "start": 1375.919,
          "duration": 4.64,
          "text": "なんか別に反応もうんうんうんうんうん"
        },
        {
          "start": 1378.4,
          "duration": 4.279,
          "text": "うんうんうんなんかままこんなもんか"
        },
        {
          "start": 1380.559,
          "duration": 4.921,
          "text": "みたいなやちょやめとこってなる人もいれ"
        },
        {
          "start": 1382.679,
          "duration": 5.921,
          "text": "ばなんかそこにやっぱ夢中になっちゃう"
        },
        {
          "start": 1385.48,
          "duration": 4.92,
          "text": "大りレビューみたいそう肉の味を覚えた"
        },
        {
          "start": 1388.6,
          "duration": 4.16,
          "text": "いうことです受けちゃったんだろうね"
        },
        {
          "start": 1390.4,
          "duration": 4.68,
          "text": "なんかで多分あだこれやっぱもうそういう"
        },
        {
          "start": 1392.76,
          "duration": 4.2,
          "text": "レビュー上だけじゃなくてま"
        },
        {
          "start": 1395.08,
          "duration": 4.92,
          "text": "Twitterとかはまさにそういう世界"
        },
        {
          "start": 1396.96,
          "duration": 6.24,
          "text": "じゃないですか肉の味を覚えた人たちが"
        },
        {
          "start": 1400.0,
          "duration": 6.32,
          "text": "たくさん生息してそうだねもうなんかその"
        },
        {
          "start": 1403.2,
          "duration": 4.44,
          "text": "肉ばっかり食おうとしてるっていうさ確か"
        },
        {
          "start": 1406.32,
          "duration": 6.28,
          "text": "Twitterだったらでもそういう場で"
        },
        {
          "start": 1407.64,
          "duration": 8.039,
          "text": "ね面白を言うていうねあの発信もしていい"
        },
        {
          "start": 1412.6,
          "duration": 6.28,
          "text": "場所だからそれはそれでまあまあいいそ"
        },
        {
          "start": 1415.679,
          "duration": 4.681,
          "text": "レビュは目的がそう目が違うからね"
        },
        {
          "start": 1418.88,
          "duration": 3.76,
          "text": "Twitterで言ったらまリプライ"
        },
        {
          "start": 1420.36,
          "duration": 5.16,
          "text": "みたいなリプライばっかりしてる人って中"
        },
        {
          "start": 1422.64,
          "duration": 6.32,
          "text": "にはいるんですけどその中でもなんか"
        },
        {
          "start": 1425.52,
          "duration": 5.6,
          "text": "ちょっと見つかるというしてるという"
        },
        {
          "start": 1428.96,
          "duration": 6.4,
          "text": "か"
        },
        {
          "start": 1431.12,
          "duration": 7.48,
          "text": "あああるねそういうのでやっぱ私一番考え"
        },
        {
          "start": 1435.36,
          "duration": 7.919,
          "text": "ちゃうのがそのミスタークソマンみたいな"
        },
        {
          "start": 1438.6,
          "duration": 8.319,
          "text": "名前でクソリプを送ってる人の二重に守ら"
        },
        {
          "start": 1443.279,
          "duration": 6.721,
          "text": "れたプライドああ僕は分かってクソリプを"
        },
        {
          "start": 1446.919,
          "duration": 9.481,
          "text": "送ってるんですよっていうところにそこを"
        },
        {
          "start": 1450.0,
          "duration": 9.72,
          "text": "直せい勝つ厳そこよねだからねすごいね"
        },
        {
          "start": 1456.4,
          "duration": 5.879,
          "text": "そううんリプって自覚したからいいって"
        },
        {
          "start": 1459.72,
          "duration": 4.64,
          "text": "わけじゃねえぞっていう心からいいと思っ"
        },
        {
          "start": 1462.279,
          "duration": 4.52,
          "text": "たことを言ってほしいなうんまそれが結果"
        },
        {
          "start": 1464.36,
          "duration": 6.679,
          "text": "クソリプだったとしてもっていうことだよ"
        },
        {
          "start": 1466.799,
          "duration": 6.48,
          "text": "ね最初からうんでつてクソリプを送り"
        },
        {
          "start": 1471.039,
          "duration": 5.561,
          "text": "続けるやつっていうのはちょっと確かに"
        },
        {
          "start": 1473.279,
          "duration": 7.081,
          "text": "うんうんよくはないよな確かになそこかも"
        },
        {
          "start": 1476.6,
          "duration": 6.559,
          "text": "しれないうん秒層はいやすごいことですよ"
        },
        {
          "start": 1480.36,
          "duration": 5.52,
          "text": "やっぱこれ本当にねえなんでみんなこんな"
        },
        {
          "start": 1483.159,
          "duration": 6.441,
          "text": "証人を欲しがるような世界になってしまっ"
        },
        {
          "start": 1485.88,
          "duration": 6.24,
          "text": "たのかでそれを俺たちが言っちゃダメなん"
        },
        {
          "start": 1489.6,
          "duration": 5.679,
          "text": "だよなそこもやっぱあるじゃんうんそう"
        },
        {
          "start": 1492.12,
          "duration": 6.88,
          "text": "そこもうん元祖アルファ行ったらあの恐れ"
        },
        {
          "start": 1495.279,
          "duration": 6.921,
          "text": "山がダヴィンチ恐れ山がそれいっちゃそう"
        },
        {
          "start": 1499.0,
          "duration": 5.96,
          "text": "初めた人間だからこのゲームをはしごを"
        },
        {
          "start": 1502.2,
          "duration": 5.28,
          "text": "登ってしまったやつが屋根の上から何を"
        },
        {
          "start": 1504.96,
          "duration": 4.839,
          "text": "言ってももう効かないんどうしようもない"
        },
        {
          "start": 1507.48,
          "duration": 5.84,
          "text": "そうそうそうお前だって登ったじゃないか"
        },
        {
          "start": 1509.799,
          "duration": 7.88,
          "text": "このはしごをそうなんですよねせめて"
        },
        {
          "start": 1513.32,
          "duration": 5.8,
          "text": "やっぱ面を外してそれは関係ないそれそう"
        },
        {
          "start": 1517.679,
          "duration": 4.281,
          "text": "いう話じゃない"
        },
        {
          "start": 1519.12,
          "duration": 7.96,
          "text": "からまだからせめてやっぱもうちょっと"
        },
        {
          "start": 1521.96,
          "duration": 9.959,
          "text": "降りてあのもう残チャン温度出してほしい"
        },
        {
          "start": 1527.08,
          "duration": 10.4,
          "text": "せめても少手心というのかちゃん温度"
        },
        {
          "start": 1531.919,
          "duration": 8.601,
          "text": "ちゃん温度だよみいそぐらいの曲は出して"
        },
        {
          "start": 1537.48,
          "duration": 6.439,
          "text": "そういうことじゃない温度を出してるか"
        },
        {
          "start": 1540.52,
          "duration": 6.48,
          "text": "せめて同としてもう少しすいいですねう"
        },
        {
          "start": 1543.919,
          "duration": 7.681,
          "text": "その残チ温度のCDのレビュー欄"
        },
        {
          "start": 1547.0,
          "duration": 7.36,
          "text": "楽しみそこはもう全解放そこは大喜会全部"
        },
        {
          "start": 1551.6,
          "duration": 6.439,
          "text": "ロでも結構ですみたい残ちゃん温度"
        },
        {
          "start": 1554.36,
          "duration": 7.96,
          "text": "レビュー大会うんこれはだからいいんじゃ"
        },
        {
          "start": 1558.039,
          "duration": 7.801,
          "text": "ないですかこれでもうあの本当"
        },
        {
          "start": 1562.32,
          "duration": 7.52,
          "text": "ティフィ何と何がどう半々なんですかそれ"
        },
        {
          "start": 1565.84,
          "duration": 7.079,
          "text": "も全然わかんなくなっちゃったはいという"
        },
        {
          "start": 1569.84,
          "duration": 5.12,
          "text": "わけなんでねまあ大喜レビューの是非は"
        },
        {
          "start": 1572.919,
          "duration": 5.76,
          "text": "ありますけども少なくとも点数はちょっと"
        },
        {
          "start": 1574.96,
          "duration": 6.48,
          "text": "あの本当に迷惑がかかってるとことなんで"
        },
        {
          "start": 1578.679,
          "duration": 5.321,
          "text": "控えましょうというところで点数は5にし"
        },
        {
          "start": 1581.44,
          "duration": 5.16,
          "text": "てください今週はこの辺ではいありがとう"
        },
        {
          "start": 1584.0,
          "duration": 6.2,
          "text": "ございました"
        },
        {
          "start": 1586.6,
          "duration": 3.6,
          "text": "ごDET"
        }
